const cleanTrainNo = (no: any) => {
  if (!no) return "";
  const s = String(no).trim();
  if (/^\d+$/.test(s)) {
    return s.padStart(5, '0');
  }
  return s;
};

const formatDateShort = (dStr: string) => {
  if (!dStr) return '';
  const parts = dStr.split('-');
  if (parts.length !== 3) return dStr;
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const day = parseInt(parts[2], 10);
  const monthIdx = parseInt(parts[1], 10) - 1;
  if (isNaN(day) || monthIdx < 0 || monthIdx > 11) return dStr;
  return `${day} ${months[monthIdx]}`;
};

const shiftDate = (dStr: string, days: number): string => {
  try {
    const parts = dStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return dStr;
    const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2], 12, 0, 0));
    d.setUTCDate(d.getUTCDate() + days);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  } catch {
    return dStr;
  }
};

const formatDateFull = (dStr: string) => {
  if (!dStr) return '';
  try {
    const parts = dStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return dStr;
    const dateObj = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2], 12, 0, 0));
    const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${dayNames[dateObj.getUTCDay()]}, ${parts[2]} ${monthNames[dateObj.getUTCMonth()]} ${parts[0]}`;
  } catch {
    return dStr;
  }
};

function getCode(val: any) {
  if (!val) return "";
  return typeof val === "string"
    ? val.toUpperCase().trim()
    : (val.code || val.stationCode || "").toUpperCase();
}

const getLegData = (leg: any) => {
  const trainNo =
    leg?.trainNo ??
    leg?.train_number ??
    leg?.number ??
    leg?.train?.trainNo ??
    leg?.train?.number ??
    null;

  const trainName =
    leg?.trainName ??
    leg?.train_name ??
    leg?.name ??
    leg?.train?.trainName ??
    "Unknown Train";

  const from = getCode(leg?.fromCode || leg?.from || leg?.fromStation || leg?.fromStationCode || leg?.from_station_code || leg?.source);
  const to   = getCode(leg?.toCode   || leg?.to   || leg?.toStation   || leg?.toStationCode   || leg?.to_station_code   || leg?.destination);

  return {
    trainNo: trainNo ? cleanTrainNo(trainNo) : "Not Available",
    trainName,
    from,
    to,
    fromCode: getCode(leg?.fromCode || leg?.fromStationCode || leg?.from_station_code || leg?.from || leg?.source),
    toCode:   getCode(leg?.toCode   || leg?.toStationCode   || leg?.to_station_code   || leg?.to   || leg?.destination)
  };
};

const getTrainInfo = (train: any) => {
  const parsed = getLegData(train);
  const rawNo = parsed.trainNo !== "Not Available" ? parsed.trainNo : (train.trainNumber || train.id || null);
  const finalNo = (String(rawNo) === "00000" || String(rawNo) === "0" || String(rawNo).includes("NaN")) ? "Train number unavailable" : cleanTrainNo(rawNo);
  return {
    number: finalNo || "Train number unavailable",
    name: parsed.trainName || train.name || "Unknown Train"
  };
};

const isSplitUnavailable = (split: any, availabilityMap: any, selectedClassByLeg: any, date: string) => {
  const legs = split.legs || split.trains || split.segments || [];
  let unavailable = false;
  legs.forEach((leg: any) => {
    const legData = getLegData(leg);
    const paddedTrainNo = cleanTrainNo(legData.trainNo);
    const currentClass = selectedClassByLeg[`${paddedTrainNo}_${legData.from}_${legData.to}`] || 'SL';
    const queryDate = leg.travelDate || date;
    const key = `${paddedTrainNo}_${legData.from}_${legData.to}_${currentClass}_${queryDate}_GN`;
    const avail = legData.trainNo ? (availabilityMap[key] || availabilityMap[`${paddedTrainNo}_${legData.from}_${legData.to}_${currentClass}_${queryDate}`]) : null;
    if (avail) {
      if ('error' in avail) {
        if (avail.type === 'unavailable') {
          unavailable = true;
        }
      } else {
        const statuses = Object.values(avail).map((v: any) => String(v.status || '').toUpperCase());
        const isRegret = statuses.some(s => s.includes('REGRET') || s.includes('NOT AVAILABLE') || s.includes('CLASS NOT AVAILABLE'));
        if (isRegret) {
          unavailable = true;
        }
      }
    }
  });
  return unavailable;
};

