/**
 * Utility for parsing and formatting train running days across Pan-India routes.
 * Supports:
 * - 7-char binary string: '1111111', '1001000' (Mon=0 .. Sun=6)
 * - 7-char Y/N string: 'YYYYYYY', 'YXXYXXX'
 * - Text keywords: 'Daily', 'All days'
 * - Array of day names: ['Mon', 'Thu'] or ['Monday', 'Thursday']
 * - Comma-separated day names: 'Mon, Thu, Sat'
 * - Sunday highlight (marked in red as per Indian Railway convention)
 */

export interface RunningDayItem {
  key: string;          // 'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'
  shortLabel: string;   // 'M', 'T', 'W', 'T', 'F', 'S', 'S'
  fullLabel: string;    // 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'
  hindiLabel: string;   // 'सोम', 'मंगल', 'बुध', 'गुरु', 'शुक्र', 'शनि', 'रवि'
  dayIndex: number;     // 0=Mon, 1=Tue, 2=Wed, 3=Thu, 4=Fri, 5=Sat, 6=Sun
  dateDayIndex: number; // JS Date.getDay(): 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat
  runs: boolean;
  isSunday: boolean;
  isSearchedDay: boolean;
}

export interface ParsedRunningDays {
  days: RunningDayItem[];
  isDaily: boolean;
  activeCount: number;
  runsOnSearchedDate: boolean;
  summaryText: string;
}

const DAY_DEFS = [
  { key: 'mon', shortLabel: 'M', fullLabel: 'Mon', hindiLabel: 'सोम', dayIndex: 0, dateDayIndex: 1, isSunday: false },
  { key: 'tue', shortLabel: 'T', fullLabel: 'Tue', hindiLabel: 'मंगल', dayIndex: 1, dateDayIndex: 2, isSunday: false },
  { key: 'wed', shortLabel: 'W', fullLabel: 'Wed', hindiLabel: 'बुध', dayIndex: 2, dateDayIndex: 3, isSunday: false },
  { key: 'thu', shortLabel: 'T', fullLabel: 'Thu', hindiLabel: 'गुरु', dayIndex: 3, dateDayIndex: 4, isSunday: false },
  { key: 'fri', shortLabel: 'F', fullLabel: 'Fri', hindiLabel: 'शुक्र', dayIndex: 4, dateDayIndex: 5, isSunday: false },
  { key: 'sat', shortLabel: 'S', fullLabel: 'Sat', hindiLabel: 'शनि', dayIndex: 5, dateDayIndex: 6, isSunday: false },
  { key: 'sun', shortLabel: 'S', fullLabel: 'Sun', hindiLabel: 'रवि', dayIndex: 6, dateDayIndex: 0, isSunday: true },
];

/**
 * Resolves which day index (0..6, where 0=Mon, 6=Sun) a YYYY-MM-DD date string represents.
 */
export function getDayIndexFromDate(dateStr?: string | null): number | null {
  if (!dateStr) return null;
  try {
    const parts = dateStr.trim().split('-');
    if (parts.length === 3) {
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const day = parseInt(parts[2], 10);
      const d = new Date(Date.UTC(year, month, day, 12, 0, 0));
      const jsDay = d.getUTCDay(); // 0=Sun, 1=Mon .. 6=Sat
      return jsDay === 0 ? 6 : jsDay - 1; // Convert to 0=Mon .. 6=Sun
    }
  } catch {
    // fallback
  }
  return null;
}

export function parseTrainRunningDays(
  rawDays: any,
  searchedDate?: string | null
): ParsedRunningDays {
  // Default: assume all days run if no explicit data exists
  const activeFlags = [true, true, true, true, true, true, true];
  let hasExplicitData = false;

  if (rawDays) {
    if (typeof rawDays === 'string') {
      const clean = rawDays.trim().toLowerCase();

      // 1. Keyword check
      if (clean === 'daily' || clean === 'all days' || clean.includes('all')) {
        hasExplicitData = true;
        // activeFlags remains all true
      }
      // 2. Binary string of length 7 ('1111111', '1001000')
      else if (/^[01]{7}$/.test(clean)) {
        hasExplicitData = true;
        for (let i = 0; i < 7; i++) {
          activeFlags[i] = clean[i] === '1';
        }
      }
      // 3. Y/N string of length 7 ('yyyyyyy', 'yxxxyxx')
      else if (/^[ynx]{7}$/.test(clean)) {
        hasExplicitData = true;
        for (let i = 0; i < 7; i++) {
          activeFlags[i] = clean[i] === 'y';
        }
      }
      // 4. Comma-separated or space-separated names ('Mon, Thu, Sat')
      else {
        const parts = clean.split(/[,\s]+/).filter(Boolean);
        if (parts.length > 0) {
          hasExplicitData = true;
          activeFlags.fill(false);
          const map: Record<string, number> = {
            'mon': 0, 'monday': 0,
            'tue': 1, 'tuesday': 1,
            'wed': 2, 'wednesday': 2,
            'thu': 3, 'thursday': 3,
            'fri': 4, 'friday': 4,
            'sat': 5, 'saturday': 5,
            'sun': 6, 'sunday': 6,
          };
          for (const p of parts) {
            for (const [name, idx] of Object.entries(map)) {
              if (p.includes(name)) {
                activeFlags[idx] = true;
                break;
              }
            }
          }
        }
      }
    } else if (Array.isArray(rawDays) && rawDays.length > 0) {
      hasExplicitData = true;
      activeFlags.fill(false);
      const map: Record<string, number> = {
        'mon': 0, 'monday': 0,
        'tue': 1, 'tuesday': 1,
        'wed': 2, 'wednesday': 2,
        'thu': 3, 'thursday': 3,
        'fri': 4, 'friday': 4,
        'sat': 5, 'saturday': 5,
        'sun': 6, 'sunday': 6,
      };
      for (const item of rawDays) {
        const str = String(item).toLowerCase().trim();
        for (const [name, idx] of Object.entries(map)) {
          if (str.includes(name)) {
            activeFlags[idx] = true;
            break;
          }
        }
      }
    }
  }

  const searchedDayIdx = getDayIndexFromDate(searchedDate);
  const activeCount = activeFlags.filter(Boolean).length;
  const isDaily = activeCount === 7;

  const days: RunningDayItem[] = DAY_DEFS.map((def, i) => ({
    ...def,
    runs: activeFlags[i],
    isSearchedDay: searchedDayIdx !== null && searchedDayIdx === i,
  }));

  const runsOnSearchedDate = searchedDayIdx !== null ? activeFlags[searchedDayIdx] : true;

  let summaryText = 'Daily Service';
  if (!isDaily) {
    if (activeCount === 1) {
      const runDay = days.find(d => d.runs);
      summaryText = `Weekly: ${runDay?.fullLabel || '1 Day'}`;
    } else {
      summaryText = `${activeCount} Days a Week`;
    }
  }

  return {
    days,
    isDaily,
    activeCount,
    runsOnSearchedDate,
    summaryText,
  };
}

