import stationsMapData from '../data/stationsMap.json';

const stationsMap: Record<string, string> = stationsMapData as Record<string, string>;
const dynamicCache: Map<string, string> = new Map();

/**
 * Register station code to name mapping discovered at runtime (e.g. from API responses)
 */
export function registerStationName(code: string, name: string): void {
  if (!code || !name) return;
  const cleanCode = code.trim().toUpperCase();
  const cleanName = name.trim();
  if (cleanCode && cleanName && cleanCode !== cleanName.toUpperCase()) {
    dynamicCache.set(cleanCode, cleanName);
  }
}

/**
 * Returns the human-readable full station name for any Indian Railway station code.
 * Example: 'BRC' -> 'Vadodara Junction'
 */
export function getStationFullName(codeOrName?: string, fallbackName?: string): string {
  if (!codeOrName && !fallbackName) return '';
  const raw = String(codeOrName || fallbackName || '').trim();
  if (!raw) return '';

  const upper = raw.toUpperCase();

  // 1. Check dynamic runtime cache
  if (dynamicCache.has(upper)) {
    return dynamicCache.get(upper)!;
  }

  // 2. Check 9,700+ Pan-India static registry
  if (stationsMap[upper]) {
    return stationsMap[upper];
  }

  // 3. If fallback name is provided and different from code, use it
  if (fallbackName && fallbackName.trim() && fallbackName.trim().toUpperCase() !== upper) {
    const cleanFallback = fallbackName.trim();
    dynamicCache.set(upper, cleanFallback);
    return cleanFallback;
  }

  // 4. If raw is already a multi-word or long name (not just a 2-4 letter code)
  if (raw.length > 5 || raw.includes(' ')) {
    return raw;
  }

  return raw;
}

/**
 * Returns formatted station name with code pill representation or string.
 * Example: 'BRC' -> 'Vadodara Junction (BRC)'
 * Example: ('BDTS', 'Bandra Terminus') -> 'Bandra Terminus (BDTS)'
 */
export function formatStationWithCode(codeOrName?: string, customName?: string): string {
  if (!codeOrName && !customName) return '';
  const rawCode = String(codeOrName || '').trim().toUpperCase();
  const fullName = getStationFullName(codeOrName, customName);

  if (!rawCode) return fullName;
  if (!fullName || fullName.toUpperCase() === rawCode) {
    return rawCode;
  }

  return `${fullName} (${rawCode})`;
}

/**
 * Returns a structured object with separated name and code for clean UI rendering.
 */
export function getStationDetails(codeOrName?: string, customName?: string): { name: string; code: string; full: string } {
  const raw = String(codeOrName || '').trim();
  const code = raw.length <= 5 && !raw.includes(' ') ? raw.toUpperCase() : '';
  const name = getStationFullName(codeOrName, customName);
  const effectiveCode = code || (customName && customName.length <= 5 ? customName.toUpperCase() : '');

  return {
    name: name || raw,
    code: effectiveCode,
    full: effectiveCode && name && name.toUpperCase() !== effectiveCode ? `${name} (${effectiveCode})` : name || raw,
  };
}

const EXCLUDED_WORDS = new Set([
  'TO', 'IN', 'AT', 'FOR', 'AND', 'ON', 'IS', 'THE', 'VIA', 'WL', 'RAC', 'CNF',
  'AVL', 'GNWL', 'PQWL', 'RLWL', 'TQWL', 'FROM', 'BOOK', 'LEG', 'STEP', 'CHECK',
  'TRAIN', 'COACH', 'SEAT', 'CLASS', 'DATE', 'SAFE', 'TIGHT', 'HIGH', 'LOW'
]);

/**
 * Sanitizes arbitrary text (such as booking steps, AI insights, route descriptions)
 * so that any bare station code like "BDTS to BRC" is replaced with "Bandra Terminus (BDTS) to Vadodara Junction (BRC)".
 * Idempotent: Does not double-wrap if already formatted like "Bandra Terminus (BDTS)".
 */
export function formatTextWithStations(text: string): string {
  if (!text) return '';
  return text.replace(/(?<!\()\b([A-Z]{2,5})\b(?!\))/g, (match, code, offset, fullStr) => {
    const upper = code.toUpperCase();
    if (EXCLUDED_WORDS.has(upper)) return match;

    const stnName = dynamicCache.get(upper) || stationsMap[upper];
    if (!stnName) return match;

    // Check if the preceding string already ends with stnName (case-insensitive)
    const preceding = fullStr.substring(0, offset).trim();
    if (preceding.toLowerCase().endsWith(stnName.toLowerCase())) {
      return match;
    }

    return `${stnName} (${upper})`;
  });
}
